def _fallback_analysis(entries: list[dict], by_agent: dict) -> dict:
    """Fallback ketika LLM gagal — buat analisis sederhana dari entries."""
    insights = []
    for agent, agent_entries in by_agent.items():
        for e in agent_entries:
            val = e.get("value", "")[:100]
            insights.append(f"[{agent}] {val}")

    return {
        "version": "v1.0",
        "engine": "kurator-v1-fallback",
        "title": f"Kurator Analysis — {len(entries)} entries from {len(by_agent)} agents",
        "summary": f"Auto-generated analysis from {len(entries)} knowledge entries.",
        "insights": insights[:5],
        "trends": [],
        "actionable": [],
        "sources": list(by_agent.keys()),
        "confidence": 0.5,
        "_fallback": True,
    }", "exit_code": 0, "error": null}

